args.ReplacementContent:
const [photo2Files, setPhoto2Files] = useState({});
const [deliveryMetadata, setDeliveryMetadata] = useState({});
const [vrnFilter, setVrnFilter] = useState('All');
const [selectedVRNForRep, setSelectedVRNForRep] = useState(null);
const [repReceivedQty, setRepReceivedQty] = useState('');
const [repAcceptedQty, setRepAcceptedQty] = useState('');
const [repChallanNo, setRepChallanNo] = useState('');
const [repRemarks, setRepRemarks] = useState('');

const renderVendorReturnsTab = () => {
  const vendorReturns = state.vendorReturns || [];
  const filteredVRNs = vrnFilter === 'All'
    ? vendorReturns
    : vendorReturns.filter(v => v.status === vrnFilter);

  const vrnFilterBtnStyle = (label) => ({
    padding: '6px 16px',
    borderRadius: '8px',
    border: vrnFilter === label ? 'none' : '1.5px solid rgba(255,255,255,0.2)',
    background: vrnFilter === label
      ? (label === 'Replacement Received' ? 'rgba(22, 163, 74, 0.85)' : label === 'Waiting Pickup' ? 'rgba(239, 68, 68, 0.85)' : 'rgba(245, 158, 11, 0.85)')
      : 'rgba(255,255,255,0.08)',
    color: '#ffffff',
    fontWeight: 800,
    fontSize: '12px',
    cursor: 'pointer',
    display: 'inline-flex',
    alignItems: 'center',
    gap: '6px',
    backdropFilter: 'blur(4px)',
    transition: 'all 0.2s',
  });

  const handleCreateReplacementGRNSubmit = (e) => {
    e?.preventDefault();
    if (!selectedVRNForRep) return;
    const payload = {
      id: 'GRN-' + Math.floor(1000 + Math.random() * 9000),
      receivedQty: Number(repReceivedQty || selectedVRNForRep.rejectedQty || 0),
      acceptedQty: Number(repAcceptedQty || selectedVRNForRep.rejectedQty || 0),
      rejectedQty: 0,
      receivedQuantity: Number(repReceivedQty || selectedVRNForRep.rejectedQty || 0),
      acceptedQuantity: Number(repAcceptedQty || selectedVRNForRep.rejectedQty || 0),
      rejectedQuantity: 0,
      orderedQty: Number(selectedVRNForRep.rejectedQty || 0),
      vendorName: selectedVRNForRep.vendorName,
      materialName: selectedVRNForRep.materialName,
      challanNo: repChallanNo || 'REP-CHALLAN',
      remarks: repRemarks || 'Replacement shipment inspected and accepted in full.'
    };
    if (typeof createReplacementGRN === 'function') {
      createReplacementGRN(selectedVRNForRep.poNumber, selectedVRNForRep.id, payload);
      showToast(`Replacement GRN created for VRN ${selectedVRNForRep.returnNo}! Sent to Finance Audit.`);
    } else {
      showToast(`Error: createReplacementGRN not available`);
    }
    setSelectedVRNForRep(null);
    setRepReceivedQty('');
    setRepAcceptedQty('');
    setRepChallanNo('');
    setRepRemarks('');
  };

  if (selectedVRNForRep) {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
        <div style={{ background: 'linear-gradient(135deg, #1e293b 0%, #0f172a 100%)', borderRadius: '16px', padding: '24px 28px', color: '#fff', boxShadow: '0 10px 25px -5px rgba(15, 23, 42, 0.25)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '16px' }}>
          <div>
            <div style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', background: 'rgba(245, 158, 11, 0.25)', border: '1px solid rgba(245, 158, 11, 0.4)', color: '#f59e0b', padding: '4px 12px', borderRadius: '20px', fontSize: '11px', fontWeight: 800, textTransform: 'uppercase' }}>
              Replacement Delivery Verification
            </div>
            <h3 style={{ fontSize: '22px', fontWeight: 900, margin: '8px 0 0 0', color: '#fff' }}>Log Replacement Goods for {selectedVRNForRep.returnNo}</h3>
            <p style={{ fontSize: '13px', color: '#94a3b8', margin: '4px 0 0 0' }}>Linked Purchase Order: {selectedVRNForRep.poNumber} | Material: {selectedVRNForRep.materialName}</p>
          </div>
          <button
            onClick={() => setSelectedVRNForRep(null)}
            style={{ padding: '8px 16px', borderRadius: '8px', background: 'rgba(255,255,255,0.1)', border: '1px solid rgba(255,255,255,0.2)', color: '#fff', fontWeight: 700, fontSize: '13px', cursor: 'pointer' }}
          >
            âœ• Back to VRN Table
          </button>
        </div>

        <form onSubmit={handleCreateReplacementGRNSubmit} style={{ background: 'var(--color-surface, #ffffff)', border: '1px solid var(--color-border, #e2e8f0)', borderRadius: '16px', padding: '28px', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.05)' }}>
          <h4 style={{ fontSize: '16px', fontWeight: 800, color: 'var(--color-text-primary, #0f172a)', margin: '0 0 20px 0' }}>Replacement Inspection details</h4>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '20px', marginBottom: '24px' }}>
            <div>
              <label style={{ display: 'block', fontSize: '12px', fontWeight: 800, color: '#475569', marginBottom: '6px' }}>Expected Replacement Qty</label>
              <input
                type="text"
                disabled
                value={`${selectedVRNForRep.rejectedQty} units`}
                style={{ width: '100%', padding: '10px 14px', borderRadius: '8px', border: '1px solid #cbd5e1', background: '#f1f5f9', fontWeight: 700, color: '#334155' }}
              />
            </div>
            <div>
              <label style={{ display: 'block', fontSize: '12px', fontWeight: 800, color: '#475569', marginBottom: '6px' }}>Received Replacement Qty *</label>
              <input
                type="number"
                required
                placeholder={String(selectedVRNForRep.rejectedQty || '')}
                value={repReceivedQty}
                onChange={e => setRepReceivedQty(e.target.value)}
                style={{ width: '100%', padding: '10px 14px', borderRadius: '8px', border: '1px solid #cbd5e1', fontWeight: 700 }}
              />
            </div>
            <div>
              <label style={{ display: 'block', fontSize: '12px', fontWeight: 800, color: '#475569', marginBottom: '6px' }}>Accepted for Stock *</label>
              <input
                type="number"
                required
                placeholder={String(selectedVRNForRep.rejectedQty || '')}
                value={repAcceptedQty}
                onChange={e => setRepAcceptedQty(e.target.value)}
                style={{ width: '100%', padding: '10px 14px', borderRadius: '8px', border: '1px solid #cbd5e1', fontWeight: 700 }}
              />
            </div>
            <div>
              <label style={{ display: 'block', fontSize: '12px', fontWeight: 800, color: '#475569', marginBottom: '6px' }}>Challan / E-Way Bill # *</label>
              <input
                type="text"
                required
                placeholder="e.g. REP-CHALLAN-902"
                value={repChallanNo}
                onChange={e => setRepChallanNo(e.target.value)}
                style={{ width: '100%', padding: '10px 14px', borderRadius: '8px', border: '1px solid #cbd5e1', fontWeight: 600 }}
              />
            </div>
          </div>
          <div style={{ marginBottom: '24px' }}>
            <label style={{ display: 'block', fontSize: '12px', fontWeight: 800, color: '#475569', marginBottom: '6px' }}>Store QC Inspection Remarks</label>
            <textarea
              rows="3"
              placeholder="Details of replacement verification..."
              value={repRemarks}
              onChange={e => setRepRemarks(e.target.value)}
              style={{ width: '100%', padding: '10px 14px', borderRadius: '8px', border: '1px solid #cbd5e1', fontWeight: 500 }}
            />
          </div>
          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px' }}>
            <button type="button" onClick={() => setSelectedVRNForRep(null)} style={{ padding: '10px 20px', borderRadius: '8px', border: '1px solid #cbd5e1', background: '#fff', fontWeight: 700, cursor: 'pointer' }}>Cancel</button>
            <button type="submit" style={{ padding: '10px 24px', borderRadius: '8px', border: 'none', background: 'linear-gradient(135deg, #10b981 0%, #059669 100%)', color: '#fff', fontWeight: 800, cursor: 'pointer', boxShadow: '0 4px 12px rgba(16, 185, 129, 0.3)' }}>Submit Replacement GRN</button>
          </div>
        </form>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
      {/* Header Banner */}
      <div style={{ background: 'linear-gradient(135deg, #0f172a 0%, #1e293b 100%)', borderRadius: '16px', padding: '24px 28px', color: '#fff', boxShadow: '0 10px 25px -5px rgba(15, 23, 42, 0.25)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '16px' }}>
        <div>
          <div style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', background: 'rgba(239, 68, 68, 0.25)', border: '1px solid rgba(239, 68, 68, 0.4)', color: '#ef4444', padding: '4px 12px', borderRadius: '20px', fontSize: '11px', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.5px', marginBottom: '8px' }}>
            Vendor Return Note (VRN) Console
          </div>
          <h3 style={{ fontSize: '22px', fontWeight: 900, margin: 0, color: '#fff' }}>Vendor Return & Replacement Management</h3>
          <p style={{ fontSize: '13px', color: '#94a3b8', margin: '4px 0 0 0' }}>Track rejected materials, vendor pickups, and replacement deliveries ({vendorReturns.length} total return records).</p>
        </div>
        {/* Filter Buttons */}
        <div style={{ display: 'flex', gap: '8px', alignItems: 'center', flexWrap: 'wrap' }}>
          {['All', 'Waiting Pickup', 'Collected', 'Replacement Pending', 'Replacement Received'].map(label => (
            <button key={label} style={vrnFilterBtnStyle(label)} onClick={() => setVrnFilter(label)}>
              {label}
            </button>
          ))}
        </div>
      </div>

      {/* Table */}
      <DataTable
        columns={[
          { key: 'returnNo', label: 'VRN #' },
          { key: 'poNumber', label: 'Linked PO #' },
          { key: 'grnNumber', label: 'Orig GRN #' },
          { key: 'vendorName', label: 'Vendor' },
          { key: 'materialName', label: 'Material' },
          { key: 'rejectedQty', label: 'Rejected Qty', render: (val, row) => <span style={{ fontWeight: 800, color: '#ef4444' }}>{val || row.rejectedQuantity || 0} units</span> },
          { key: 'reason', label: 'Rejection Reason', render: val => <span style={{ fontSize: '12px', color: '#475569' }}>{val || 'Quality Check Issue'}</span> },
          { key: 'returnDate', label: 'Return Date' },
          { key: 'status', label: 'Status', render: val => <StatusBadge status={val || 'Waiting Pickup'} /> },
          {
            key: 'actions',
            label: 'Actions',
            render: (_, row) => (
              <div style={{ display: 'flex', gap: '8px' }}>
                {(!row.status || row.status === 'Waiting Pickup') && (
                  <button
                    onClick={() => {
                      if (typeof updateVendorReturnStatus === 'function') {
                        updateVendorReturnStatus(row.id || row.returnNo, 'Collected');
                        showToast(`VRN ${row.returnNo} marked as Collected by Vendor.`);
                      }
                    }}
                    style={{ padding: '6px 12px', borderRadius: '6px', border: '1px solid #3b82f6', background: 'rgba(59, 130, 246, 0.1)', color: '#2563eb', fontWeight: 700, fontSize: '11px', cursor: 'pointer' }}
                  >
                    Mark Collected
                  </button>
                )}
                {(row.status === 'Collected' || row.status === 'Replacement Pending' || row.status === 'Waiting Pickup') && (
                  <button
                    onClick={() => {
                      setSelectedVRNForRep(row);
                      setRepReceivedQty(String(row.rejectedQty || ''));
                      setRepAcceptedQty(String(row.rejectedQty || ''));
                    }}
                    style={{ padding: '6px 12px', borderRadius: '6px', border: 'none', background: 'linear-gradient(135deg, #10b981 0%, #059669 100%)', color: '#fff', fontWeight: 700, fontSize: '11px', cursor: 'pointer', boxShadow: '0 2px 6px rgba(16,185,129,0.3)' }}
                  >
                    Log Replacement Delivery
                  </button>
                )}
              </div>
            )
          }
        ]}
        data={filteredVRNs}
        emptyMessage="No vendor return notes match this filter."
      />
    </div>
  );
};

const renderPOWorkspace = () => {
  const tabs = ["Create Request", "PO List", "Verify Delivery", "Vendor Returns"];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
      {/* Tab Header Bar */}
      <div style={{
        display: 'flex',
        borderBottom: '1px solid var(--color-border)',
        gap: '8px',
        paddingBottom: '4px'
      }}>
        {tabs.map(tab => {
          const isActive = activeTab === tab || (tab === "Verify Delivery" && activeTab === "Awaiting Deliveries") || (tab === "Awaiting Deliveries" && activeTab === "Verify Delivery");
          return (
            <button
              key={tab}
              onClick={() => {
                handleTabChange(tab === "Awaiting Deliveries" ? "Verify Delivery" : tab);
              }}
              style={{
                padding: '10px 20px',
                background: isActive ? 'var(--color-primary)' : 'transparent',
                color: isActive ? '#000' : 'var(--color-text-secondary)',
                border: 'none',
                borderRadius: '8px',
                fontWeight: '700',
                fontSize: '13.5px',
                cursor: 'pointer',
                transition: 'all 0.2s ease',
                display: 'flex',
                alignItems: 'center',
                gap: '6px'
              }}
            >
              {tab}
            </button>
          );
        })}
      </div>

      {/* Tab Contents */}
      {activeTab === "Create Request" && renderPOCreateRequestTab()}
      {(activeTab === "PO List" || activeTab === "Indent Ledger") && renderPOListTab()}
      {(activeTab === "Verify Delivery" || activeTab === "Awaiting Deliveries") && renderPOVerifyDeliveryTab()}
      {activeTab === "Vendor Returns" && renderVendorReturnsTab()}
    </div>
  );
};

