args.ReplacementContent:
const [deliveryMetadata, setDeliveryMetadata] = useState({});
const [vrnFilter, setVrnFilter] = useState('All');
const [selectedVRNForRep, setSelectedVRNForRep] = useState(null);
const [repReceivedQty, setRepReceivedQty] = useState('');
const [repAcceptedQty, setRepAcceptedQty] = useState('');
const [repInvoice, setRepInvoice] = useState('');
const [repChallan, setRepChallan] = useState('');
const [repRemarks, setRepRemarks] = useState('');

useEffect(() => {
  if (currentView === 'grn-inspection' || currentView === 'grn') {
    setActiveTab('Verify Delivery');
  } else if (currentView === 'vendor-returns' || currentView === 'replacement-receipts') {
    setActiveTab('Vendor Returns');
  } else {
    const currentParams = new URLSearchParams(location.search);
    const currentTab = currentParams.get('tab');
    setActiveTab(currentTab || 'PO List');
  }
}, [location.search, currentView]);

// Reset selected PO when switching tabs to ensure the full list table is displayed first
useEffect(() => {
  if (activeTab === 'Verify Delivery' || activeTab === 'Awaiting Deliveries') {
    // Keep selectedPO as null when entering the tab so the entire PO table (`all po list wise`) is displayed first
  }
}, [activeTab]);

const handleTabChange = (tab) => {
  setSelectedPO(null);
  setActiveTab(tab);
  let viewPath = 'purchase';
  if (currentView === 'grn-inspection') {
    viewPath = 'grn-inspection';
  } else if (currentView === 'vendor-returns') {
    viewPath = 'vendor-returns';
  } else if (currentView === 'po') {
    viewPath = 'po';
  }
