const getProductStock = (productName) => {
  const item = (state.rawInventory || []).find(r => r.material === productName || r.name === productName);
  return item ? (item.stock || 0) : 0;
};

const handleProductSelection = (productName) => {
  setArProduct(productName);
  const item = (state.rawInventory || []).find(r => r.material === productName || r.name === productName);
  if (item) {
    setArProductCode(item.code || `RM-${Date.now().toString().slice(-4)}`);
    setArUnit(item.unit || 'Units');
    setArAffectedQuantity(0);
    setArOccurrenceCount(1);
  } else {
    setArProductCode(`RM-${Date.now().toString().slice(-4)}`);
  }
};

const renderAnalysisRequestsWorkspace = () => {
  const requests = state.analysisRequests || [];
  const requestId = params?.slug?.[1];
  const isCreate = requestId === 'create';
  const isEdit = params?.slug?.[2] === 'edit';
  const isDetails = requestId && !isCreate && !isEdit;

  // Filters
  const filteredRequests = requests.filter(req => {
    // search
    const matchesSearch = arSearchQuery === '' ||
      req.requestNumber?.toLowerCase().includes(arSearchQuery.toLowerCase()) ||
      req.storeReport?.productName?.toLowerCase().includes(arSearchQuery.toLowerCase()) ||
      req.storeReport?.brand?.toLowerCase().includes(arSearchQuery.toLowerCase()) ||
      req.storeReport?.problemTitle?.toLowerCase().includes(arSearchQuery.toLowerCase());

    if (!matchesSearch) return false;

    // tab filter
    if (arActiveTab === 'All') return true;
    if (arActiveTab === 'Drafts') return req.status === 'DRAFT';
    if (arActiveTab === 'Pending Finance') return req.status === 'PENDING_FINANCE_REVIEW' || req.status === 'FINANCE_UNDER_REVIEW';
    if (arActiveTab === 'Returned to Store') return req.status === 'RETURNED_TO_STORE';
    if (arActiveTab === 'Pending Decision') return req.status === 'PENDING_SUPER_ADMIN_APPROVAL' || req.status === 'RETURNED_TO_FINANCE';
    if (arActiveTab === 'Under Trial') return req.status === 'TRIAL_APPROVED' || req.status === 'TRIAL_IN_PROGRESS' || req.status === 'TRIAL_REPORT_SUBMITTED';
    if (arActiveTab === 'Completed') return req.status === 'COMPLETED';
    if (arActiveTab === 'Rejected') return req.status === 'FINANCE_REJECTED' || req.status === 'SUPER_ADMIN_REJECTED';
    return true;
  });

  const activeTabStyle = (tab) => ({
    padding: '10px 18px',
    borderRadius: '8px',
    background: arActiveTab === tab ? 'var(--color-primary)' : 'transparent',
    color: arActiveTab === tab ? '#000' : 'var(--color-text-secondary)',
    border: 'none',
    fontWeight: '700',
    fontSize: '13px',
    cursor: 'pointer',
    transition: 'all 0.2s'
  });

  const resetForm = () => {
    setArProduct('');
    setArProductCode('');
    setArBrand('');
    setArIssueType('Quality Issue');
    setArPriority('MEDIUM');
    setArProblemTitle('');
    setArDescription('');
    setArFirstObservedDate('');
    setArOccurrenceCount('');
    setArAffectedQuantity('');
    setArUnit('Bags');
    setArObservation('');
    setArImmediateAction('');
    setArSuggestedAlternativeBrand('');
    setArAttachments([]);
  };

  const handleFormSubmit = (e, isDraft = false) => {
    e?.preventDefault();
    // Validation
    if (!arProduct || !arBrand || !arProblemTitle || !arDescription) {
      showToast('Please fill out all required operational fields.');
      return;
    }
    if (Number(arOccurrenceCount) < 0 || Number(arAffectedQuantity) < 0) {
      showToast('Occurrence count and affected quantity cannot be negative.');
      return;
    }

    const payload = {
      createdBy: user?.name || 'Store Executive',
      storeReport: {
        productId: arProductCode || `RM-${Date.now()}`,
        productCode: arProductCode || `RM-${Date.now()}`,
        productName: arProduct,
        brand: arBrand,
        issueType: arIssueType,
        priority: arPriority,
        problemTitle: arProblemTitle,
        description: arDescription,
        firstObservedDate: arFirstObservedDate || new Date().toISOString().split('T')[0],
        occurrenceCount: Number(arOccurrenceCount) || 0,
        affectedQuantity: Number(arAffectedQuantity) || 0,
        unit: arUnit,
        currentStock: getProductStock(arProduct),
        observation: arObservation,
        immediateAction: arImmediateAction,
        suggestedAlternativeBrand: arSuggestedAlternativeBrand,
        attachments: arAttachments
      }
    };

    if (isDraft) {
      saveAnalysisRequestDraft(payload);
      showToast('Analysis request draft saved successfully!');
    } else {
      createAnalysisRequest(payload);
      showToast('Analysis request submitted to Finance review!');
    }
    resetForm();
    navigate.push('/store/analysis-requests');
  };

  const handleFormUpdate = (e, submitDirect = false) => {
    e?.preventDefault();
    if (!arProduct || !arBrand || !arProblemTitle || !arDescription) {
      showToast('Please fill out all required operational fields.');
      return;
    }

    const payload = {
      performedBy: user?.name || 'Store Executive',
      storeReport: {
        productName: arProduct,
        productCode: arProductCode,
        brand: arBrand,
        issueType: arIssueType,
        priority: arPriority,
        problemTitle: arProblemTitle,
        description: arDescription,
        firstObservedDate: arFirstObservedDate,
        occurrenceCount: Number(arOccurrenceCount) || 0,
        affectedQuantity: Number(arAffectedQuantity) || 0,
        unit: arUnit,
        observation: arObservation,
        immediateAction: arImmediateAction,
        suggestedAlternativeBrand: arSuggestedAlternativeBrand,
        attachments: arAttachments
      }
    };

    updateAnalysisRequest(requestId, payload);
    if (submitDirect) {
      submitAnalysisRequest(requestId);
      showToast('Analysis request updated and submitted successfully!');
    } else {
      showToast('Analysis request operational details updated!');
    }
    resetForm();
    navigate.push('/store/analysis-requests');
  };

  const loadRequestToForm = (req) => {
    if (!req?.storeReport) return;
    setArProduct(req.storeReport.productName || '');
    setArProductCode(req.storeReport.productCode || '');
    setArBrand(req.storeReport.brand || '');
    setArIssueType(req.storeReport.issueType || 'Quality Issue');
    setArPriority(req.storeReport.priority || 'MEDIUM');
    setArProblemTitle(req.storeReport.problemTitle || '');
    setArDescription(req.storeReport.description || '');
    setArFirstObservedDate(req.storeReport.firstObservedDate || '');
    setArOccurrenceCount(String(req.storeReport.occurrenceCount || ''));
    setArAffectedQuantity(String(req.storeReport.affectedQuantity || ''));
    setArUnit(req.storeReport.unit || 'Bags');
    setArObservation(req.storeReport.observation || '');
    setArImmediateAction(req.storeReport.immediateAction || '');
    setArSuggestedAlternativeBrand(req.storeReport.suggestedAlternativeBrand || '');
    setArAttachments(req.storeReport.attachments || []);
  };

  // Render Request Creation
  if (isCreate) {
    return (
      <div style={{ background: '#fff', padding: '30px', borderRadius: '16px', border: '1px solid #cbd5e1' }}>
        <div style={{ borderBottom: '2px solid #f1f5f9', paddingBottom: '16px', marginBottom: '24px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <h3 style={{ fontSize: '20px', fontWeight: 900, color: '#0f172a', margin: 0 }}>Create Product & Brand Analysis Request</h3>
            <p style={{ fontSize: '13px', color: '#64748b', marginTop: '4px' }}>Fill operational problem report details to initiate review.</p>
          </div>
          <button onClick={() => { resetForm(); navigate.push('/store/analysis-requests'); }} style={{ padding: '8px 16px', background: '#f1f5f9', border: '1px solid #cbd5e1', borderRadius: '8px', cursor: 'pointer', fontWeight: 700 }}>Cancel</button>
        </div>

        <form onSubmit={(e) => handleFormSubmit(e, false)} style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
          <div>
            <label style={{ display: 'block', fontSize: '12px', fontWeight: 800, color: '#334155', marginBottom: '6px' }}>Select Product *</label>
            <select required value={arProduct} onChange={(e) => handleProductSelection(e.target.value)} style={{ width: '100%', padding: '11px 14px', border: '1.5px solid #cbd5e1', borderRadius: '10px' }}>
              <option value="">-- Choose Raw Material --</option>
              {(state.rawInventory || []).map(r => (
                <option key={r.code || r.material} value={r.material}>{r.material}</option>
              ))}
            </select>
          </div>
          <div>
            <label style={{ display: 'block', fontSize: '12px', fontWeight: 800, color: '#334155', marginBottom: '6px' }}>Product Code (Auto)</label>
            <input type="text" readOnly value={arProductCode} style={{ width: '100%', padding: '11px 14px', border: '1.5px solid #e2e8f0', borderRadius: '10px', background: '#f8fafc' }} />
