        <div>
          <div style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', background: 'rgba(59, 130, 246, 0.25)', border: '1px solid rgba(59, 130, 246, 0.4)', color: '#60a5fa', padding: '4px 12px', borderRadius: '20px', fontSize: '11px', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.5px', marginBottom: '8px' }}>
            Store Operations Control
          </div>
          <h3 style={{ fontSize: '22px', fontWeight: 900, margin: 0, color: '#fff' }}>Product & Brand Analysis Directory</h3>
          <p style={{ fontSize: '13px', color: '#94a3b8', margin: '4px 0 0 0' }}>Report recurring material/brand defects and monitor approved technical trials.</p>
        </div>
        <button
          onClick={() => navigate.push('/store/analysis-requests/create')}
          style={{ padding: '10px 20px', border: 'none', background: 'linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%)', color: '#fff', borderRadius: '8px', fontWeight: 800, fontSize: '13px', cursor: 'pointer', display: 'inline-flex', alignItems: 'center', gap: '6px', boxShadow: '0 4px 12px rgba(37,99,235,0.3)' }}
        >
          <Plus size={16} /> Create Request
        </button>
      </div>

      {/* Tab Filters */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid #cbd5e1', paddingBottom: '6px', flexWrap: 'wrap', gap: '16px' }}>
        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
          {['All', 'Drafts', 'Pending Finance', 'Returned to Store', 'Pending Decision', 'Under Trial', 'Completed', 'Rejected'].map(t => (
            <button key={t} onClick={() => setArActiveTab(t)} style={activeTabStyle(t)}>
              {t}
            </button>
          ))}
        </div>
        <div style={{ position: 'relative' }}>
          <input type="text" placeholder="Search requests..." value={arSearchQuery} onChange={e => setArSearchQuery(e.target.value)} style={{ padding: '8px 14px 8px 32px', border: '1.5px solid #cbd5e1', borderRadius: '8px', fontSize: '13px', width: '220px' }} />
          <Search size={16} style={{ position: 'absolute', left: '10px', top: '11px', color: '#94a3b8' }} />
        </div>
      </div>

      {/* DataTable requests */}
      <DataTable
        columns={[
          { header: 'Request #', accessor: 'requestNumber', render: (row) => <strong style={{ color: '#2563eb' }}>{row.requestNumber}</strong> },
          { header: 'Product Name', accessor: 'storeReport.productName', render: (row) => row.storeReport?.productName },
          { header: 'Brand', accessor: 'storeReport.brand', render: (row) => row.storeReport?.brand },
          { header: 'Problem Title', accessor: 'storeReport.problemTitle', render: (row) => row.storeReport?.problemTitle },
          { header: 'Priority', accessor: 'storeReport.priority', render: (row) => <span style={{ color: row.storeReport?.priority === 'CRITICAL' ? '#ef4444' : '#64748b', fontWeight: 800 }}>{row.storeReport?.priority}</span> },
          { header: 'Submitted Date', accessor: 'submittedAt', render: (row) => row.submittedAt ? new Date(row.submittedAt).toLocaleDateString() : 'N/A' },
          { header: 'Status', accessor: 'status', render: (row) => <StatusBadge status={row.status || 'DRAFT'} /> },
          {
            header: 'Actions',
            accessor: 'actions',
            render: (row) => (
              <div style={{ display: 'flex', gap: '8px' }}>
                <button
                  onClick={() => navigate.push(`/store/analysis-requests/${row.id}`)}
                  style={{ padding: '5px 12px', background: '#f1f5f9', border: '1px solid #cbd5e1', borderRadius: '6px', fontSize: '12px', fontWeight: 700, cursor: 'pointer' }}
                >
                  View Details
                </button>
                {(row.status === 'DRAFT' || row.status === 'RETURNED_TO_STORE') && (
                  <button
                    onClick={() => navigate.push(`/store/analysis-requests/${row.id}/edit`)}
                    style={{ padding: '5px 12px', background: 'linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%)', color: '#fff', border: 'none', borderRadius: '6px', fontSize: '12px', fontWeight: 700, cursor: 'pointer' }}
                  >
                    Edit Report
                  </button>
                )}
                {row.status === 'DRAFT' && (
                  <button
                    onClick={() => {
                      submitAnalysisRequest(row.id);
                      showToast(`Request ${row.requestNumber} submitted to Finance!`);
                    }}
                    style={{ padding: '5px 12px', background: 'linear-gradient(135deg, #10b981 0%, #059669 100%)', color: '#fff', border: 'none', borderRadius: '6px', fontSize: '12px', fontWeight: 700, cursor: 'pointer' }}
                  >
                    Submit
                  </button>
                )}
              </div>
            )
          }
        ]}
        data={filteredRequests}
        emptyMessage="No product analysis requests found for the selected tab."
      />
    </div>
  );
};

